CHUNK = '            f"{origin}: rule missing required fields: {sorted(missing)}"\n        )\n\n    rid = obj["id"]\n    if not isinstance(rid, str) or not rid:\n        raise StandardConfigurationError(f"{origin}: rule id must be a non-empty string")\n\n    level = obj["level"]\n    delivery = obj["delivery"]\n    override_policy = obj["override_policy"]\n    if level not in VALID_LEVELS:\n        raise StandardConfigurationError(f"{rid}: invalid level {level!r}")\n    if delivery not in VALID_DELIVERY:\n        raise StandardConfigurationError(f"{rid}: invalid delivery {delivery!r}")\n    if override_policy not in VALID_OVERRIDE_POLICIES:\n        raise StandardConfigurationError(\n            f"{rid}: invalid override_policy {override_policy!r}"\n        )\n\n    instruction = obj["instruction"]\n    if not isinstance(instruction, str) or not instruction.strip():\n        raise StandardConfigurationError(f"{rid}: instruction must be non-empty")\n\n    applies = obj["applies_to"]\n    if not isinstance(applies, dict):\n        raise StandardConfigurationError(f"{rid}: applies_to must be an object")\n\n    profiles = _as_tuple_str(applies.get("profiles", []), "applies_to.profiles", rid)\n    languages = _as_tuple_str(applies.get("languages", []), "applies_to.languages", rid)\n    paths = _as_tuple_str(applies.get("paths", []), "applies_to.paths", rid)\n\n    verification_obj = obj["verification"]\n    if not isinstance(verification_obj, dict):\n        raise StandardConfigurationError(f"{rid}: verification must be an object")\n    verification_type = verification_obj.get("type")\n    verification_ref = verification_obj.get("ref")\n    if verification_type not in VALID_VERIFICATION_TYPES:\n        raise StandardConfigurationError(\n            f"{rid}: invalid verification.type {verification_type!r}"\n        )\n    if verification_ref is not None and not isinstance(verification_ref, str):\n        raise StandardConfigurationError(f"{rid}: verification.ref must be string|null")\n\n    # Locked reachability invariant:\n    # a reactive rule must have an executable deterministic trigger.\n    if delivery == "on_failure" and verification_type not in EXECUTABLE_FAILURE_TYPES:\n        raise StandardConfigurationError(\n            f"{rid}: delivery=on_failure requires an executable verification trigger; "\n            f"got verification.type={verification_type!r}"\n        )\n    if delivery == "on_failure" and not verification_ref:\n        raise StandardConfigurationError(\n            f"{rid}: delivery=on_failure requires verification.ref"\n        )\n\n    sources = _as_tuple_str(obj["sources"], "sources", rid)\n    if not sources:\n        raise StandardConfigurationError(f"{rid}: sources must not be empty")\n\n    specializes = obj.get("specializes")\n'
